<?php $title='Pagos';require __DIR__.'/../layouts/header.php'; ?><div class="app-shell"><?php require __DIR__.'/../layouts/sidebar.php'; ?><main class="main"><header class="page-head"><div><div class="breadcrumb">GESTIÓN / <strong>Pagos</strong></div><h1>Pagos y cobranzas</h1><p>Registra pagos parciales o totales y consulta el historial.</p></div></header><?php require __DIR__.'/../layouts/flash.php'; ?><section class="panel"><div class="panel-heading"><div><h2>Registrar pago</h2><p>El sistema valida que el importe no supere el saldo pendiente.</p></div></div><form class="inline-form" method="post" action="index.php?page=payment-save"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><select name="reservation_id" required><option value="">Seleccionar reserva *</option><?php foreach($reservations as $r): if((float)$r['balance']>0): ?><option value="<?=$r['id']?>"><?=e($r['code'])?> · <?=e($r['client_name'])?> · saldo <?=e(money($r['balance']))?></option><?php endif; endforeach; ?></select><input type="number" name="amount" min="0.01" step="0.01" placeholder="Monto en Bs *" required><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required><select name="method"><option>Transferencia</option><option>Efectivo</option><option>Tarjeta</option><option>QR</option><option>Otro</option></select><input name="reference" placeholder="N.º de referencia"><input name="notes" placeholder="Observaciones"><button class="btn primary">＋ Registrar pago</button></form></section><section class="panel section-gap"><div class="panel-heading"><div><h2>Historial de pagos</h2><p><?=count($payments)?> pago(s) registrados</p></div></div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>RESERVA</th><th>CLIENTE</th><th>MÉTODO</th><th>REFERENCIA</th><th>MONTO</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?=e($p['payment_date'])?></td><td><strong><?=e($p['code'])?></strong></td><td><?=e($p['client_name'])?></td><td><?=e($p['method'])?></td><td><?=e($p['reference']?:'—')?></td><td><strong><?=e(money($p['amount']))?></strong></td></tr><?php endforeach; if(!$payments): ?><tr><td colspan="6" class="empty">Todavía no hay pagos registrados.</td></tr><?php endif; ?></tbody></table></div></section><footer class="page-footer">NETA Gestión Integral <span>Control administrativo; no sustituye un sistema contable</span></footer></main></div><?php require __DIR__.'/../layouts/footer.php'; ?>
